{

"kind": "propose",
"summary": "The renderer container's CPU limit is too low, causing throttling. Increase its limit to 1.5 CPU cores.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Renderer is throttled at 1 CPU limit with 0.93 usage, and previous revision 3 had similar throttling but was healthy.",
    "supporting": ["ev-container_cpu", "ev-revision_health"],
    "contradicting": [],
    "missing": ["container_logs_tail", "pod_states"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "New version 4's renderer uses 0.93 CPU (vs 0.39 throttled ratio in revision 3), but previous version was also throttled.",
    "supporting": ["ev-container_cpu", "ev-revision_health"],
    "contradicting": ["throttling_came_with_rollout"],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise renderer's CPU limit to 1.5 cores to clear throttling, as usage is 0.93 of 1 core and throttling is sustained.",
  "rationale": "Throttling is sustained (41% ratio) with usage near limit (0.93), and previous revision 3 had similar throttling but was healthy. New version 4's renderer uses more CPU than before, but the limit is still too low. Raising it to 1.5 cores should alleviate the throttling without touching memory or removing limits.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-revision_health", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app", "throttling_came_with_rollout", "earlier_revision_healthy"]
}
}
